(() => {
 const originalRows=rows,originalRender=render;
 const text=id=>document.getElementById('field_'+id).value.trim();
 function commit(change){const before=structuredClone(data);change();if(!persist()){data=before;return false}render();return true}
 function required(id,label){if(text(id))return true;const input=document.getElementById('field_'+id);input.focus();toast(label+' is required.');return false}
 function linkedArtist(name){return data.artists.find(a=>a.name===name)}
 function linkedShow(title){return data.shows.find(s=>s.title===title)}
 rows=function(type){
  if(type==='show')return data.shows.length?data.shows.map((s,i)=>'<div class="row"><div><b>'+escape(s.title)+'</b><small>'+s.works+' assigned works · '+(s.status==='Draft'?'Hidden from guests':'Visible in this local presentation')+'</small></div><span class="tag">'+escape(s.status)+'</span>'+action('Edit','editShow('+i+')','small')+action('Preview','previewShow('+i+')','small')+action(s.status==='Draft'?'Publish demo':'Return to draft','toggleShow('+i+')','small')+'</div>').join(''):'<div class="row"><small>No exhibitions. Create a draft to begin.</small></div>';
  if(type==='work')return data.works.length?data.works.map((w,i)=>'<div class="row" data-search="'+escape((w.name+' '+w.artist).toLowerCase())+'"><div><b>'+escape(w.name)+'</b><small>'+escape(w.artist)+' · '+escape(w.price)+'</small></div><span class="tag">'+escape(w.status)+'</span>'+action('View','openArtwork('+i+')','small')+action('Edit','editWork('+i+')','small')+action('Remove','removeArtwork('+i+')','small danger')+'</div>').join(''):'<div class="row"><small>No artworks. Add a work, image and story to begin.</small></div>';
  if(type==='lead')return data.leads.length?data.leads.map((l,i)=>'<div class="row"><div><b>'+escape(l.name||'Guest')+'</b><small>'+escape(l.interest)+' · '+escape(l.status)+'</small></div>'+action('Read enquiry','readLead('+i+')','small')+action('Update status','advanceLead('+i+')','small')+'</div>').join(''):'<div class="row"><small>No enquiries yet. Presentation enquiries stay on this browser.</small></div>';
  return originalRows(type);
 };
 render=function(){anansiFrontend.normalize(data);originalRender();const search=document.querySelector('.search');if(search){search.setAttribute('aria-label','Search catalogue');search.oninput=()=>{const query=search.value.trim().toLowerCase(),cards=document.querySelectorAll('.work-card');cards.forEach(card=>card.hidden=!card.textContent.toLowerCase().includes(query))};search.onkeydown=event=>{if(event.key==='Enter'){go('artworks');setTimeout(()=>{const input=document.getElementById('catalogueSearch');input.value=search.value;input.dispatchEvent(new Event('input'))},0)}}}
  if(page==='artworks'){const input=document.createElement('input');input.id='catalogueSearch';input.className='search';input.placeholder='Search title or artist';input.setAttribute('aria-label','Search artworks');input.style.marginBottom='16px';document.querySelector('#artworks .table').before(input);input.oninput=()=>document.querySelectorAll('#artworks [data-search]').forEach(row=>row.hidden=!row.dataset.search.includes(input.value.trim().toLowerCase()))}
  const date=document.querySelector('.utility .date');if(date)date.textContent=new Date().toLocaleDateString('en-GB',{timeZone:'Africa/Lagos',weekday:'long',day:'numeric',month:'long',year:'numeric'});
  const metrics=document.querySelectorAll('.metric b');if(metrics[0])metrics[0].textContent=data.shows.filter(s=>s.status!=='Draft').length;if(metrics[1])metrics[1].textContent=data.works.filter(w=>w.placement&&w.placement!=='Storage / unplaced'&&anansiFrontend.visible(w,data)).length;
  const fake=document.querySelector('.mini.aqua b');if(fake){fake.textContent='Local demo';fake.style.fontSize='14px';document.querySelector('.mini.aqua span').textContent='PRESENTATION STATUS'}
 };
 newShow=()=>openForm('Create draft exhibition',[{id:'title',label:'EXHIBITION TITLE'},{id:'description',label:'CURATOR INTRODUCTION',type:'textarea'}],()=>{if(!required('title','Exhibition title'))return;if(data.shows.some(s=>s.title.toLowerCase()===text('title').toLowerCase())){toast('Use a unique exhibition title.');return}if(commit(()=>data.shows.push({id:anansiFrontend.id(),title:text('title'),description:text('description'),status:'Draft',works:0}))){modal.close();go('exhibitions');toast('Draft saved. Assign works, preview, then publish the demo.')}});
 window.editShow=i=>{const s=data.shows[i];openForm('Edit exhibition',[{id:'title',label:'EXHIBITION TITLE',value:s.title},{id:'description',label:'CURATOR INTRODUCTION',type:'textarea',value:s.description||''}],()=>{if(!required('title','Exhibition title'))return;const title=text('title');if(data.shows.some((other,index)=>index!==i&&other.title.toLowerCase()===title.toLowerCase())){toast('Use a unique exhibition title.');return}if(commit(()=>{data.works.filter(w=>w.showId===s.id||w.show===s.title).forEach(w=>{w.show=title;w.showId=s.id});s.title=title;s.description=text('description')})){modal.close();toast('Exhibition updated.')}})};
 window.previewShow=i=>{location.href='gallery.html?mode=curator&exhibition='+encodeURIComponent(data.shows[i].id)};
 window.toggleShow=i=>{const s=data.shows[i];if(s.status==='Draft'&&!data.works.some(w=>w.showId===s.id&&w.placement&&w.placement!=='Storage / unplaced')){toast('Assign at least one placed artwork before publishing.');return}if(commit(()=>s.status=s.status==='Draft'?'Published':'Draft'))toast('Exhibition '+s.status.toLowerCase()+' in the demo. Reload open gallery tabs to see changes.')};
 newArtist=()=>openForm('Add artist',[{id:'name',label:'ARTIST DISPLAY NAME'}],()=>{if(!required('name','Display name'))return;if(data.artists.some(a=>a.name.toLowerCase()===text('name').toLowerCase())){toast('That artist is already in the roster.');return}if(commit(()=>data.artists.push({id:anansiFrontend.id(),name:text('name'),works:0}))){modal.close();toast('Artist added without contact details.')}});
 editArtist=i=>{const artist=data.artists[i];openForm('Edit artist',[{id:'name',label:'ARTIST DISPLAY NAME',value:artist.name}],()=>{if(!required('name','Display name'))return;if(data.artists.some((a,index)=>index!==i&&a.name.toLowerCase()===text('name').toLowerCase())){toast('That display name is already used.');return}if(commit(()=>{data.works.filter(w=>w.artistId===artist.id||w.artist===artist.name).forEach(w=>{w.artist=text('name');w.artistId=artist.id});artist.name=text('name')})){modal.close();toast('Artist and linked artworks updated.')}})};
 function workForm(index=null){const work=index===null?{}:data.works[index];openForm(index===null?'Add artwork':'Edit artwork',[
  {id:'title',label:'ARTWORK TITLE',value:work.name},{id:'artist',label:'ARTIST',type:'select',options:['Unassigned',...data.artists.map(a=>a.name)],value:work.artist},{id:'format',label:'ARTWORK TYPE',type:'select',options:['Painting','Sculpture','Mixed media','Digital work'],value:work.format||'Painting'},
  {id:'show',label:'EXHIBITION',type:'select',options:['Exhibition not assigned',...data.shows.map(s=>s.title)],value:work.show||'Exhibition not assigned'},{id:'placement',label:'VIRTUAL GALLERY PLACEMENT',type:'select',options:placements,value:work.placement||'Storage / unplaced'},
  {id:'price',label:'PRICE',value:work.price,placeholder:'Price on request'},{id:'image',label:'ARTWORK IMAGE · PNG / JPEG / WEBP, MAX 1.5 MB',type:'file',accept:'image/png,image/jpeg,image/webp'},
  {id:'coverage',label:'SCULPTURE MODEL · SELF-CONTAINED GLB, MAX 25 MB',type:'file',accept:'.glb'},{id:'story',label:'ARTWORK STORY',type:'textarea',value:work.story}
 ],async()=>{if(!required('title','Artwork title'))return;const imageFile=document.getElementById('field_image').files[0],modelFile=document.getElementById('field_coverage').files[0],format=text('format'),placement=text('placement');
  const zone=window.anansiPlacementZones[placement];if(zone&&((format==='Sculpture')!==(zone.kind==='plinth'))){toast('Sculptures require a plinth. Other works require a wall.');return}
  if(imageFile&&(imageFile.size>1500000||!['image/png','image/jpeg','image/webp'].includes(imageFile.type))){toast('Choose a PNG, JPEG or WEBP below 1.5 MB.');return}
  if(modelFile&&(format!=='Sculpture'||modelFile.size>25000000||!modelFile.name.toLowerCase().endsWith('.glb'))){toast('Use a sculpture GLB below 25 MB.');return}
  const saveButton=document.getElementById('saveModal');saveButton.disabled=true;saveButton.textContent='Saving…';try{
   let image=work.image||'',assetKey=work.assetKey||'',assetName=work.assetName||'';if(imageFile)image=await fileToDataUrl(imageFile);
   if(modelFile){const buffer=await modelFile.arrayBuffer(),header=new DataView(buffer);if(buffer.byteLength<20||header.getUint32(0,true)!==0x46546c67||header.getUint32(4,true)!==2||header.getUint32(8,true)!==buffer.byteLength)throw Error('This is not a valid GLB 2 model.');const length=header.getUint32(12,true);if(length+20>buffer.byteLength)throw Error('GLB header is invalid.');const json=JSON.parse(new TextDecoder().decode(buffer.slice(20,20+length)));if([...(json.buffers||[]),...(json.images||[])].some(item=>item.uri&&!item.uri.startsWith('data:')))throw Error('Use a self-contained GLB without external files.');const triangles=(json.meshes||[]).flatMap(m=>m.primitives||[]).reduce((n,p)=>n+(json.accessors?.[p.indices??p.attributes?.POSITION]?.count||0)/3,0);if(triangles>150000)throw Error('Reduce this model below 150,000 triangles for the web preview.');assetKey=anansiFrontend.id();await anansiAssets.put(assetKey,modelFile);assetName=modelFile.name}
   const artist=text('artist'),show=text('show'),entry={...work,id:work.id||anansiFrontend.id(),name:text('title'),artist,artistId:linkedArtist(artist)?.id||null,format,show:show==='Exhibition not assigned'?'':show,showId:linkedShow(show)?.id||null,placement,price:text('price')||'Price on request',status:work.status||'Available',image,assetKey,assetName,story:text('story'),note:'Curator catalogue entry'};
   if(commit(()=>{if(index===null)data.works.push(entry);else data.works[index]=entry})){modal.close();go('artworks');toast('Artwork saved on this device. Reload the gallery to install it.')}
  }catch(error){toast(error.message||'Asset could not be stored. Please try a smaller file.')}finally{saveButton.disabled=false;saveButton.textContent='Save'}
 });}
 newWork=()=>workForm();window.editWork=i=>workForm(i);
 window.readLead=i=>{const lead=data.leads[i];document.getElementById('modalTitle').textContent='Collector enquiry';document.getElementById('form').innerHTML='<p><b>'+escape(lead.name||'Guest')+'</b> · '+escape(lead.interest)+'</p><p>'+escape(lead.message||'No message added.')+'</p><p>'+escape(lead.status)+' · local presentation record</p><p>No contact details are required. Live replies will use the guest’s private inbox.</p>';document.getElementById('saveModal').style.display='none';modal.showModal()};
 const previousPlacement=setPlacement;setPlacement=(i,placement)=>{const zone=window.anansiPlacementZones[placement];if(zone&&((data.works[i].format==='Sculpture')!==(zone.kind==='plinth'))){toast('Choose a compatible wall or sculpture plinth.');render();return}previousPlacement(i,placement)};
 removeArtwork=i=>{const work=data.works[i];if(!confirm('Remove “'+work.name+'” from the catalogue? Use Undo immediately; leaving this page or making another change dismisses it.'))return;if(commit(()=>data.works.splice(i,1))){toast('Artwork removed.');const undo=document.createElement('button');undo.className='btn small';undo.textContent='Undo';undo.onclick=()=>{if(commit(()=>data.works.splice(Math.min(i,data.works.length),0,work))){undo.remove();toast('Artwork restored.')}};document.querySelector('.content .view.active').prepend(undo)}};
 removeArtist=i=>{const artist=data.artists[i];if(!confirm('Remove '+artist.name+' from the roster? Their artworks will remain unassigned.'))return;const previous=structuredClone(data);if(commit(()=>{data.works.filter(w=>w.artistId===artist.id||w.artist===artist.name).forEach(w=>{w.artist='Unassigned';w.artistId=null});data.artists.splice(i,1)})){const undo=document.createElement('button');undo.className='btn small';undo.textContent='Undo artist removal';undo.onclick=()=>{if(commit(()=>{data.artists.splice(Math.min(i,data.artists.length),0,artist);for(const old of previous.works){const current=data.works.find(w=>w.id===old.id);if(current&&(old.artistId===artist.id||old.artist===artist.name)){current.artist=old.artist;current.artistId=artist.id}}})){undo.remove();toast('Artist restored.')}};document.querySelector('.view.active').prepend(undo)}};
 const note=document.createElement('p');note.className='demo-workspace-note';note.textContent='Curator presentation workspace · browser-local data · no authentication or live publishing';document.querySelector('.content').prepend(note);
 persist();render();
})();
